 glance=[["Format", "Computer-based, multiple-choice questions"], ["Questions and marks", "100 questions, 1 mark each, 100 marks"], ["Duration", "2 hours"], ["Passing score", "60 marks (60%)"], ["Negative marking", "25% of a question's marks, so 0.25 per wrong answer"], ["Certificate validity", "Three years; renew through NISM"], ["Where it leads", "Currency derivative dealing and advisory roles"]],
 checklist=["Practise futures profit and loss until it is automatic.", "Learn contract specifications: lot size, tick, expiry, settlement.", "Draw payoffs for long and short calls and puts.", "Revise margin types and daily settlement.", "Take Mock 5 with negative marking."],
 tips=["Futures pay off in rupees: lot size x price change.", "Read the quote carefully: USD-INR means rupees per dollar.", "A call gains when the currency rises, a put when it falls.", "Break-even for a long call is strike plus premium.", "Eliminate two options before guessing; wrong answers cost marks."],
